    heritageTitle: "穆拉诺玻璃简史",
    heritageBody1:
      "1291 年以前，穆拉诺岛上就已经有人制作玻璃。那一年，威尼斯下令将城内的玻璃窑炉迁到岛上。通常认为此举是为了防火，也让威尼斯更容易管理这门重要的生意。此后几个世纪，穆拉诺以 Cristallo、水晶般透明的玻璃、Lattimo 乳白玻璃、Filigrana 玻璃丝工艺和玻璃珠闻名。这些技艺至今仍在岛上实践，并由熟练的工匠在工坊中传授。",
    heritageBody2:
      "手工加工的玻璃很少能做出完全相同的两件：一颗小气泡、色调的细微变化，或略有不同的弧度。我们挑选加入系列的首饰时，也会留意这些细节。",
