const dictionaries: Record<Locale, Dictionary> = { en, it, fr, de, ar, zh, ru, es, pt, hi, ja, nl, pl, cs, sv, ro };

export function getDictionary(locale: Locale): Dictionary {
  return dictionaries[locale];
}
